import { escHTML, escURL } from "@ntgovernment/squiz-factory/utils/xss";

const FILE_ICONS = {
  pdf: "fa-file-pdf",
  doc: "fa-file-word",
  docx: "fa-file-word",
  ppt: "fa-file-powerpoint",
  pptx: "fa-file-powerpoint",
  xls: "fa-file-excel",
  xlsx: "fa-file-excel",
};
const DEFAULT_FILE_ICON = "fa-file";

function fileIconClass(fileType) {
  const key = String(fileType ?? "").toLowerCase();
  return FILE_ICONS[key] || DEFAULT_FILE_ICON;
}

/**
 * fns.resolveUri wraps its result in a { ok, data } envelope -- confirmed
 * against a live Squiz DXP backend (see card.spec.md assumption 4, the same
 * mechanism reused here). Checking for the `data` key's presence, not just
 * truthiness, avoids misreading a legitimate `{ data: null }` "not found"
 * envelope as the raw asset itself.
 */
function unwrapResolved(result) {
  if (!result || typeof result !== "object") return null;
  if ("data" in result) return result.data ?? null;
  return result;
}

async function resolveAsset(uri, fns) {
  if (!uri || typeof fns?.resolveUri !== "function") return null;
  try {
    const result = await fns.resolveUri(uri);
    return unwrapResolved(result);
  } catch {
    return null;
  }
}

/**
 * File type/extension is read from the resolved asset's own URL rather
 * than a metadata field -- reliable regardless of what (if any) type
 * attribute the resolved asset schema exposes. See document.spec.md
 * assumption 1.
 */
function fileTypeFromUrl(url) {
  const match = /\.([a-z0-9]+)(?:[?#].*)?$/i.exec(String(url ?? ""));
  return match ? match[1].toLowerCase() : "";
}

/**
 * Per the real Matrix asset schema (confirmed via `card`'s own live-tested
 * usage), `metadata` is a key-value map where every value is an array of
 * strings -- this reads the first value for a given key.
 */
function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? (value[0] || "") : "";
}

function renderDocument(resolved, download) {
  if (!resolved) return "";

  const title = resolved.name || "";
  const href = resolved.url || "";
  const fileType = fileTypeFromUrl(href);
  const fileSize = resolved.attributes?.file_size_readable || "";
  const description = firstMetadataValue(resolved.metadata, "page-description");
  const metaLine = [fileType.toUpperCase(), fileSize].filter(Boolean).join(" | ");

  const descriptionHtml = description
    ? `<p class="document__description">${escHTML(description)}</p>`
    : "";

  return /*html*/`
<div class="document">
  <div class="document__header">
    <div class="document__icon-wrapper">
      <div class="document__icon">
        <i class="fa-thin ${fileIconClass(fileType)}" aria-hidden="true"></i>
      </div>
    </div>
    <div class="document__meta">
      <a href="${escURL(href)}" class="document__title"${download ? " download" : ""}>${escHTML(title)}</a>
      <span class="document__info">${escHTML(metaLine)}</span>
    </div>
  </div>
  ${descriptionHtml}
</div>`;
}

export default {
  async main(input, info) {
    const { assets = [], download = false } = input || {};
    const sources = Array.isArray(assets) ? assets : [];

    const resolvedList = await Promise.all(
      sources.map((uri) => resolveAsset(uri, info?.fns)),
    );

    const cardsHtml = resolvedList
      .map((resolved) => renderDocument(resolved, download))
      .filter(Boolean)
      .join("\n");

    return /*html*/`
<div class="document-list">
  ${cardsHtml}
</div>
`;
  },
};
